#include "KS/SRC/vector3d_shared.h"

#define PAD_U 1
#define PAD_D 2
#define PAD_L 3
#define PAD_R 4
#define PAD_UL 5
#define PAD_UR 6
#define PAD_DL 7
#define PAD_DR 8
#define assert(condition) ((void)0)

class input_device {
protected:
    int device_id;

public:
    virtual ~input_device();
};

class AISurferController : public input_device {
private:
    enum AI_SURFER_STATE {
        STATE_STANDING,
        STATE_CHASE,
        STATE_DO_TRICK,
        STATE_AVOID_SURFER,
        STATE_BOUNCE_AROUND_WAVE,
        STATE_LAST_STATE
    };

    enum AI_SURFER_SUBSTATE {
        NO_SUBSTATE,
        TRICK_APPROACH,
        TRICK_LAUNCH,
        TRICK_DOING_TRICK,
        TRICK_LANDING,
        TRICK_DONE,
        STATE_LAST_SUBSTATE
    };

    vector3d target;
    vector3d toTube;
    vector3d right;
    vector3d velocity;
    vector3d dir;
    vector3d paddleDirVec;
    AI_SURFER_STATE myState;
    AI_SURFER_SUBSTATE mySubstate;
    float offdh;
    float diffAngle;
    float paddleAngle;
    float toTargetDistance;
    float lastToTargetDistance;
    float relativeVelocityToTarget;
    float lastRelativeVelocityToTarget;
    float toTubeDist;
    float last_toward_tube_velocity;
    float this_toward_tube_velocity;
    vector3d heading;
    float acel;
    float oldAcel;
    void *ksctl;
    bool hitRegionPocket;
    float X;
    float Y;
    float XRight;
    float YRight;
    bool ButtonX;
    bool ButtonO;
    bool ButtonSq;
    bool ButtonTr;
    bool ButtonL1;
    bool ButtonL2;
    bool ButtonL3;
    bool ButtonR1;
    bool ButtonR2;
    bool ButtonR3;
    bool ButtonSelect;
    bool ButtonStart;

public:
    virtual ~AISurferController();
    void pressDir(int which, float howmuch);
};

void AISurferController::pressDir(int which, float howmuch)
{
  assert(howmuch <= 1.05 && howmuch >=-.05);
  switch (which)
  {
    case PAD_L:
      X = -howmuch;
      break;
    case PAD_R:
      X = howmuch;
      break;
    case PAD_U:
      Y = -howmuch;
      break;
    case PAD_D:
      Y = howmuch;
      break;
    case PAD_UL:
      pressDir(PAD_L, howmuch);
      pressDir(PAD_U, howmuch);
      break;
    case PAD_UR:
      pressDir(PAD_R, howmuch);
      pressDir(PAD_U, howmuch);
      break;
    case PAD_DL:
      pressDir(PAD_L, howmuch);
      pressDir(PAD_D, howmuch);
      break;
    case PAD_DR:
      pressDir(PAD_R, howmuch);
      pressDir(PAD_D, howmuch);
      break;
  }
}
